package com.igareck.antidpi;import android.content.Context;import java.io.FileDescriptor;public class TapSession {public volatile int opens,cancels,closes;public boolean failCloseOnce,cleanupOk=true;public java.util.concurrent.CountDownLatch cancelEntered,cancelRelease;interface Observer {void checkpoint(String tap,boolean visibility)throws Exception;}public TapSession(Context c){}public TapSession(Context c,Observer o){}static void restoreTestInterfaceVisibility(Context c){}public void open(){opens++;}boolean reusable(){return opens>0&&cancels==0&&closes==0;}public void cancel(){cancels++;if(cancelEntered!=null){cancelEntered.countDown();try{cancelRelease.await(3,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}}public void close(){closes++;cleanupOk=!failCloseOnce;failCloseOnce=false;}public String progress(){return "{\"cleanup_ok\":"+cleanupOk+"}";}public FileDescriptor descriptor(){return new FileDescriptor();}public byte[] configuration(){return new byte[0];}}
